// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {airPort} from "../src/airPort.sol";

contract InvMutTest is Test {
    airPort c;
    function setUp() public { c = new airPort(); }

    // fuzz parameters: a from address and a boolean deciding whether the callee should revert
    function testFuzz_property(address fromAddr, bool shouldRevert) public {
        // keep fromAddr non-zero to be a valid address in domain
        vm.assume(fromAddr != address(0));

        // make exactly one recipient to keep observations simple and to match C's loop behavior
        address[] memory tos = new address[](1);

        // deploy a helper that either reverts or succeeds when transferFrom is called
        FailingOrRecordingReceiver helper = new FailingOrRecordingReceiver(shouldRevert);
        tos[0] = address(helper);

        // call transfer and observe whether it completes (does not revert)
        bool ok;
        try c.transfer(fromAddr, address(helper), tos, 1) {
            ok = true;
        } catch {
            ok = false;
        }

        // The reference C requires the external call to succeed, so when helper is set to revert,
        // reference C must revert (ok == false). This property states that ok == (!shouldRevert).
        // The mutant that ignores the callee's success can return true even when shouldRevert==true,
        // so this assertion will fail on the mutant for some fuzz input (shouldRevert==true).
        assertTrue(ok == (!shouldRevert));
    }
}

// Adversarial counterparty: when called with transferFrom selector, either revert or record
contract FailingOrRecordingReceiver {
    bool public shouldRevert;
    // record last call args for potential inspection (not used by test assertion, but useful)
    address public lastFrom;
    address public lastTo;
    uint256 public lastValue;

    constructor(bool _shouldRevert) payable {
        shouldRevert = _shouldRevert;
    }

    // match the selector transferFrom(address,address,uint256)
    function transferFrom(address from, address to, uint256 value) external returns (bool) {
        if (shouldRevert) {
            revert("forced revert");
        }
        lastFrom = from;
        lastTo = to;
        lastValue = value;
        return true;
    }

    // fallback to be safe
    fallback() external payable {}
    receive() external payable {}
}
